// These tests run without root: they check the generated bytecode, not the
// kernel's opinion of it (that is TestLoadAndCount, behind the ebpf tag).

func TestValueLayout(t *testing.T) {
	var v value
	if unsafe.Sizeof(v) != valueLen || unsafe.Offsetof(v.Tx) != offTx || unsafe.Offsetof(v.Comm) != offComm {
		t.Errorf("value layout: size %d, tx at %d, comm at %d", unsafe.Sizeof(v), unsafe.Offsetof(v.Tx), unsafe.Offsetof(v.Comm))
	}
	if valueAt+valueLen > stackKey || valueAt%8 != 0 {
		t.Error("on-stack value overlaps the key or is misaligned")
	}
}

func TestProgramEncodes(t *testing.T) {
	for _, dir := range []Direction{Rx, Tx} {
		insns := program(4, dir)
		var adds int
		for i, ins := range insns {
			if ins.OpCode == asm.InvalidOpCode {
				t.Fatalf("instruction %d is invalid: %v", i, ins)
			}
			if ins.OpCode == asm.StoreXAddOp(asm.DWord) {
				adds++
				if ins.Offset != dir.offset() {
					t.Errorf("atomic add at offset %d, want %d", ins.Offset, dir.offset())
				}
			}
		}
		if adds != 2 {
			t.Errorf("want 2 atomic adds (existing entry, lost insert race), got %d", adds)
		}
		if insns[0].Offset != 4*8 {
			t.Errorf("reads ctx slot at %d, want 32", insns[0].Offset)
		}
		// labels must resolve and every map reference must be one map
		var buf bytes.Buffer
		if err := insns.Marshal(&buf, binary.LittleEndian); err != nil {
			t.Fatalf("marshal: %v", err)
		}
	}
}

func TestSocketOwnerProgramsEncode(t *testing.T) {
	progs := map[string]asm.Instructions{"create": sockCreateProgram(), "rx": skbProgram(Rx), "tx": skbProgram(Tx)}
	for name, insns := range progs {
		for i, ins := range insns {
			if ins.OpCode == asm.InvalidOpCode {
				t.Fatalf("%s: instruction %d is invalid: %v", name, i, ins)
			}
		}
		var buf bytes.Buffer
		if err := insns.Marshal(&buf, binary.LittleEndian); err != nil {
			t.Fatalf("%s: marshal: %v", name, err)
		}
		// cgroup programs must return 1 (allow) on every path, or whyslow
		// would drop traffic
		last := insns[len(insns)-2]
		if last.OpCode != asm.Mov.Op(asm.ImmSource) || last.Constant != 1 {
			t.Errorf("%s: exit path returns %v", name, last)
		}
	}
	_, v := ownerTypes()
	if sz, err := btf.Sizeof(v); err != nil || sz != ownerLen {
		t.Errorf("owner value BTF size %d, %v; want %d", sz, err, ownerLen)
	}
}

func TestProgNames(t *testing.T) {
	seen := map[string]bool{}
	for _, h := range Hooks {
		n := progName(h)
		if len(n) > 15 || seen[n] {
			t.Errorf("program name %q too long or duplicate", n)
		}
		seen[n] = true
	}
}

func TestSlotFromBTF(t *testing.T) {
	i32 := &btf.Int{Name: "int", Size: 4, Encoding: btf.Signed}
	sizeT := &btf.Typedef{Name: "size_t", Type: &btf.Int{Name: "unsigned long", Size: 8}}
	ptr := &btf.Pointer{Target: &btf.Void{}}
	param := func(name string, t btf.Type) btf.FuncParam { return btf.FuncParam{Name: name, Type: t} }
	fn := func(name string, ret btf.Type, ps ...btf.FuncParam) *btf.Func {
		return &btf.Func{Name: name, Type: &btf.FuncProto{Return: ret, Params: ps}}
	}
	var b btf.Builder
	for _, f := range []*btf.Func{
		fn("tcp_sendmsg", i32, param("sk", ptr), param("msg", ptr), param("size", sizeT)),
		fn("tcp_cleanup_rbuf", &btf.Void{}, param("sk", ptr), param("copied", i32)),
		// 6.1 signature (5 arguments); before 5.19 it had a 6th, "noblock"
		fn("udp_recvmsg", i32, param("sk", ptr), param("msg", ptr), param("len", sizeT), param("flags", i32), param("addr_len", ptr)),
		fn("bad_ret", sizeT, param("sk", ptr)),
	} {
		if _, err := b.Add(f); err != nil {
			t.Fatal(err)
		}
	}
	raw, err := b.Marshal(nil, nil)
	if err != nil {
		t.Fatal(err)
	}
	spec, err := btf.LoadSpecFromReader(bytes.NewReader(raw))
	if err != nil {
		t.Fatal(err)
	}
	cases := []struct {
		h    Hook
		want int
		ok   bool
	}{
		{Hook{Func: "tcp_sendmsg", Exit: true}, 3, true},
		{Hook{Func: "tcp_cleanup_rbuf", Arg: 1}, 1, true},
		{Hook{Func: "udp_recvmsg", Exit: true}, 5, true},
		{Hook{Func: "tcp_cleanup_rbuf", Arg: 0}, 0, false}, // a pointer, not a count
		{Hook{Func: "tcp_cleanup_rbuf", Arg: 2}, 0, false}, // no such argument
		{Hook{Func: "bad_ret", Exit: true}, 0, false},      // size_t is not int
		{Hook{Func: "missing", Exit: true}, 0, false},
	}
	for _, c := range cases {
		got, err := c.h.Slot(spec)
		if (err == nil) != c.ok || (c.ok && got != c.want) {
			t.Errorf("%s exit=%v arg=%d: slot %d, err %v; want %d ok=%v", c.h.Func, c.h.Exit, c.h.Arg, got, err, c.want, c.ok)
		}
	}
}

func TestCommString(t *testing.T) {
	if got := commString([]byte("curl\x00\x00junk")); got != "curl" {
		t.Errorf("got %q", got)
	}
	if got := commString([]byte("exactly16bytes!!")); got != "exactly16bytes!!" {
		t.Errorf("got %q", got)
	}
}
